const body = $('Search Zilliz').first().json;
const hits = body.data || [];

const context = hits.map((h, i) => {
  const text = h.text ?? h.entity?.text ?? '';
  const title = h.title ?? h.entity?.title ?? '';
  const category = h.category ?? h.entity?.category ?? '';
  const url = h.url ?? h.entity?.url ?? '';
  return `[${i + 1}] ${title} (${category})\n${text}\nSource: ${url}`;
}).join('\n\n');

const question = $('Webhook').first().json.body.message;

// The exact text of the bot's immediately preceding reply, sent by the
// frontend itself (not fetched from Mem0). This is the reliable signal for
// "did I just offer a doctor" -- it's synchronous and always current, unlike
// Mem0 history below, which processes saves as an async background job and
// isn't guaranteed to be ready by the very next message.
const lastBotMessage = $('Webhook').first().json.body.last_bot_message || '';

// Older Mem0 history - best-effort supplementary context only. May lag or be
// empty due to Mem0's async processing; do not rely on it for the immediate
// "was there just an offer" check, that's what lastBotMessage above is for.
let historyItems = [];
try {
  const histJson = $('Get Recent History (Mem0)').first().json;
  historyItems = histJson.results || histJson.memories || histJson.data || [];
} catch (e) {
  historyItems = [];
}
const olderHistory = historyItems.slice(-6).map((m) => {
  const role = m.role || m.actor || 'user';
  const content = m.memory || m.content || m.text || '';
  return `${role}: ${content}`;
}).join('\n') || '(none available)';

const prompt = `You are a medical assistant for Altibbi. Respond in the SAME language the user's latest message is written in (Arabic or English) - match it exactly, do not switch languages and do not mix languages.

Answer the user's question using ONLY the context below, taken from Altibbi articles. If the context doesn't contain enough information to answer safely, say so clearly and recommend seeing a doctor.

Never recommend or name a specific doctor yourself. If (and only if) the user's latest message describes a personal symptom or health complaint, end your written answer with one short, natural follow-up question offering to suggest a specialist doctor near them in Jordan. Do not offer this for general or informational questions that aren't about the user's own health, and do not repeat the offer if you can see below that you already made it and are waiting on an answer.

Your own immediately preceding reply in this conversation (this is reliable and current -- use this specifically to judge whether you just made a doctor-offer that the user's latest message might now be confirming, or whether you're already mid-way through a doctor-related exchange):
${lastBotMessage || '(none - this is the first message in the conversation)'}

Older conversation history, for general background only (may be incomplete or delayed, do not use this alone to judge whether an offer was just made):
${olderHistory}

Context:
${context}

User's latest message: ${question}

Reply with ONLY a raw JSON object (no markdown fences, no extra text, no trailing commentary) with exactly these fields:
{
  "answer": "your full written answer, in the user's language, including the follow-up question if applicable",
  "language": "ar or en",
  "doctor_relevant": true or false,
  "confirmed_doctor_request": true or false,
  "specialty_query": "the medical specialty to search for, in Arabic, matching how Jordanian clinics label specialties (e.g. "جلدية", "قلب", "أطفال") - empty string if not applicable"
}

Set "confirmed_doctor_request" to true if EITHER of these is true: (a) your immediately preceding reply above already offered a doctor recommendation and the user's latest message is agreeing to it (e.g. "yes", "نعم", "ok please"), OR (b) the user's latest message is itself a direct request for a doctor/specialist recommendation, even with no prior offer (e.g. "can you recommend a doctor", "I need a doctor", "أعطني دكتور", "دكتور من فضلك"). Otherwise false. When true, set "specialty_query" based on the most relevant condition or symptom discussed anywhere in this conversation so far (your preceding reply and the older history above, plus the latest message) - not only the latest message, since a direct request like "can you recommend a doctor" may not repeat the symptom itself.`;

return [{ json: { prompt, question } }];

