const raw = $json.candidates[0].content.parts[0].text;
let html = raw.replace(/^```html\s*/i, '').replace(/```\s*$/i, '').trim();

// add these two lines here:
html = html.replace(/<[^>]*>\s*(primary\s+)?language\s*(detected)?\s*:?\s*(english|arabic|mixed)?\s*<\/[^>]*>/gi, '');
html = html.replace(/^\s*(primary\s+)?language\s*(detected)?\s*:?\s*(english|arabic|mixed)\s*$/gim, '');

const arabicChars = (raw.match(/[\u0600-\u06FF]/g) || []).length;
const isArabic = arabicChars > raw.length * 0.15;

const dir = isArabic ? 'rtl' : 'ltr';
const align = isArabic ? 'right' : 'left';
const headerTitle = isArabic ? 'ملخص محادثتك الطبية' : 'Your Medical Conversation Summary';
const footerText = isArabic
  ? 'هذا الملخص لأغراض إعلامية فقط ولا يغني عن استشارة الطبيب.'
  : 'This summary is for informational purposes only and does not replace consulting a doctor.';
const emailSubject = isArabic ? 'ملخص محادثتك الطبية' : 'Your Medical Conversation Summary';

const wrapped = `
<div dir="${dir}" style="font-family: Arial, sans-serif; line-height: 1.8; color: #222222; max-width: 600px; margin: 0 auto; padding: 24px; background: #f9f9f7; border-radius: 8px; border: 1px solid #e2e2de; text-align: ${align};">
  <div style="background: #0f6e56; color: #ffffff; padding: 16px 24px; border-radius: 8px 8px 0 0; margin: -24px -24px 20px -24px;">
    <h2 style="margin:0; font-size: 20px; font-weight: 500;">${headerTitle}</h2>
  </div>
  <div style="font-size: 15px;">${html}</div>
  <hr style="border:none; border-top:1px solid #ddd; margin: 24px 0;">
  <p style="font-size: 12px; color: #888888; text-align:center; margin:0;">${footerText}</p>
</div>`;

return [{ json: { emailHtml: wrapped, emailSubject: emailSubject } }];

