const item = $input.first();

let audioB64 = null;
if (item.binary && item.binary.data) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  audioB64 = buffer.toString('base64');
}

const replyText = $('Gemini Answer (RAG)').first().json.candidates[0].content.parts[0].text;
const sessionId = $('Webhook').first().json.body.session_id;

return [{ json: { reply: replyText, audio_base64: audioB64, mime_type: 'audio/mpeg', session_id: sessionId } }];

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Model didn't return clean JSON - fall back to the raw text as the
  // answer so the chat still works, just without doctor-offer logic.
  parsed = {
    answer: raw || 'Sorry, something went wrong generating a response.',
    language: 'en',
    doctor_relevant: false,
    confirmed_doctor_request: false,
    specialty_query: ''
  };
}

return [{
  json: {
    answer: parsed.answer || '',
    language: parsed.language || 'en',
    doctor_relevant: !!parsed.doctor_relevant,
    confirmed_doctor_request: !!parsed.confirmed_doctor_request,
    specialty_query: parsed.specialty_query || ''
  }
}];

const rows = $input.all().map((i) => i.json).filter((r) => r && r.doctor_id);

const language = $('Parse Gemini JSON').first().json.language || 'en';
const isArabic = language === 'ar';

let block;
if (!rows.length) {
  block = isArabic
    ? '\u0644\u0645 \u0623\u062c\u062f \u062d\u0627\u0644\u064a\u0627\u064b \u0623\u0637\u0628\u0627\u0621 \u0645\u0637\u0627\u0628\u0642\u064a\u0646 \u0641\u064a \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0644\u0647\u0630\u0627 \u0627\u0644\u062a\u062e\u0635\u0635.'
    : "I couldn't find a matching doctor in the database for that specialty right now.";
} else {
  const lines = rows.map((d, i) => {
    const parts = [];
    parts.push(`${i + 1}. ${d.name || '-'} \u2014 ${d.specialty || '-'}`);
    if (d.location) parts.push((isArabic ? '\u0627\u0644\u0645\u0648\u0642\u0639: ' : 'Location: ') + d.location);
    if (d.phone) parts.push((isArabic ? '\u0627\u0644\u0647\u0627\u062a\u0641: ' : 'Phone: ') + d.phone);
    if (d.hours) parts.push((isArabic ? '\u0645\u0648\u0627\u0639\u064a\u062f \u0627\u0644\u062f\u0648\u0627\u0645: ' : 'Hours: ') + d.hours);
    if (d.insurance) parts.push((isArabic ? '\u0627\u0644\u062a\u0623\u0645\u064a\u0646 \u0627\u0644\u0645\u0642\u0628\u0648\u0644: ' : 'Insurance accepted: ') + d.insurance);
    if (d.profile_url) parts.push((isArabic ? '\u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0634\u062e\u0635\u064a: ' : 'Profile: ') + d.profile_url);
    return parts.join('\n');
  });
  const intro = isArabic
    ? '\u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0637\u0644\u0628\u0643\u060c \u0625\u0644\u064a\u0643 \u0628\u0639\u0636 \u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u0627\u0644\u0645\u062a\u0627\u062d\u064a\u0646 (\u0647\u0630\u0647 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0644\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0641\u0642\u0637 \u0648\u0644\u064a\u0633\u062a \u0625\u062d\u0627\u0644\u0629 \u0637\u0628\u064a\u0629 \u0631\u0633\u0645\u064a\u0629\u060c \u064a\u0631\u062c\u0649 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0627\u0644\u062d\u062c\u0632 \u0645\u0628\u0627\u0634\u0631\u0629 \u0645\u0639 \u0627\u0644\u0639\u064a\u0627\u062f\u0629):'
    : "Based on what you asked, here are a few available doctors (this is informational only, not a formal referral - please confirm directly with the clinic before visiting):";
  block = intro + '\n\n' + lines.join('\n\n');
}

return [{ json: { doctorBlock: block } }];

const parsed = $('Parse Gemini JSON').first().json;
let finalText = parsed.answer || '';

let doctorBlock = null;
try {
  doctorBlock = $json.doctorBlock || null;
} catch (e) {
  doctorBlock = null;
}

if (doctorBlock) {
  finalText = finalText + '\n\n' + doctorBlock;
}

// Reshaped to match a raw Gemini response so the existing downstream nodes
// (Respond - Chat Answer, Rewrite for Speech, Save Turn to Mem0 (Chat)) keep
// working unmodified - they all read $json.candidates[0].content.parts[0].text.
return [{
  json: {
    candidates: [ { content: { parts: [ { text: finalText } ] } } ]
  }
}];

const raw = ($json.candidates?.[0]?.content?.parts?.[0]?.text || '').trim();
const cleaned = raw.replace(/```/g, '').replace(/^["']|["']$/g, '').trim();

// Re-validate against the real list rather than trusting Gemini's output blindly --
// this also protects the parameterized query below from ever receiving something
// that isn't a real value already present in the doctors table.
const validSpecialties = $('Get Distinct Specialties').all().map(i => i.json.specialty);
const matched = cleaned !== 'NONE' && validSpecialties.includes(cleaned);

return [{
  json: {
    matched_specialty: matched ? cleaned : null,
    specialtyMatched: matched
  }
}];
